"""Explicit frozen reference templates -> real native bounded checks, no oracle training."""
from pathlib import Path
import sys,json,subprocess,re
from interlock.scenario import fingerprint
root=Path(sys.argv[1]);names=['retry-conflict','retry-fixed','retry-envelope-branch-failure','retry-envelope-fixed'];base=[sys.executable,'-m','interlock','case-template',*[p for name in names for p in ['--fixture',name]]];native=subprocess.run(base,capture_output=True,text=True);assert native.returncode==0,native.stderr;manifest=json.loads(native.stdout);assert [row['id']for row in manifest['cases']]==names;assert [row['expected_status']for row in manifest['cases']]==['merge_interaction_found','no_interaction_within_bound','branch_failure','no_interaction_within_bound'];html=subprocess.run(base+['--html'],capture_output=True,text=True);assert html.returncode==0,html.stderr;assert json.loads(re.search(r'<script id="report-data" type="application/json">(.*?)</script>',html.stdout,re.S).group(1))==manifest;(root/'draft.html').write_text(html.stdout);(root/'draft.json').write_text(json.dumps(manifest));path=root/'manifest.json';path.write_text(json.dumps(manifest));before=path.read_bytes();run=subprocess.run([sys.executable,'-m','interlock','check-cases',str(path),'--max-depth','12','--summary'],capture_output=True,text=True);assert run.returncode==3,run.stderr+run.stdout;report=json.loads(run.stdout);assert report['status']=='incomplete'and report['execution_scope']=='model_only'and report['source_verification']=='not_checked';assert [row['observed_status']for row in report['cases'][:2]]==[row['expected_status']for row in manifest['cases'][:2]];assert all(row['observed_status']=='incomplete'for row in report['cases'][2:]);selected=subprocess.run([sys.executable,'-m','interlock','check-cases',str(path),'--max-depth','12','--summary',*[p for name in names[:2]for p in ['--case',name]]],capture_output=True,text=True);assert selected.returncode==0,selected.stderr+selected.stdout;assert json.loads(selected.stdout)['omitted_cases']==2;assert path.read_bytes()==before
for extra in [['--fixture','retry-conflict'],['--fixture','unknown']]:
 bad=subprocess.run(base+extra,capture_output=True,text=True);assert bad.returncode==2 and not bad.stdout
# Generation must not call bounded search or trusted handler checks.
code="from unittest.mock import patch;from interlock.cli import main\nwith patch('interlock.model_cases.check_cases',side_effect=RuntimeError('search forbidden')),patch('interlock.fixture.check_fixture',side_effect=RuntimeError('handler execution forbidden')):raise SystemExit(main(['case-template','--fixture','retry-fixed']))\n"
static=subprocess.run([sys.executable,'-c',code],capture_output=True,text=True);assert static.returncode==0,static.stderr

